    'companion.hijriTitle': 'Ọjọ́ Hijri tí a ṣe iṣiro',
    'companion.hijriOff': 'Ìfihàn ọjọ́ tí a ṣe iṣiro kò ṣiṣẹ́.',
    'companion.counterTitle': 'Olùkàpọ̀ àṣírí',
    'companion.counterOff': 'Olùkàpọ̀ àṣírí kò ṣiṣẹ́.',
    'companion.counterLede': 'Ohun èlò rírọ̀rùń láti tọ́jọ́ kíkà nígbà tí ojú ìwé yìí bá ṣí.',
    'companion.counterPrivacy':
      'A kò tọ́jọ́ kíkà rẹ́ kò sì fi ránṣẹ́ sí AyahSpring. Ìkọ̀ ẹ̀ẹ̀méjì yóò pa á rẹ́. Aṣàwákiri rẹ́ lè mú ojú ìwé náà padà fún ìgbà díẹ̀ tí o bá padà sẹ́yìn. Kò ṣe ìṣọ̀papọ̀ láàárín àwọn ẹ̀rọ̀ tàbí àwọn àkọ̀ọ̀ntọ̀.',
    'companion.cardPrayerBody': 'Ṣe ìṣiro àwọn àkókó lórí ẹ̀rọ̀ rẹ́ kí o sì jẹ́rìí pẹ̀lú àwùjọ́ àdúgbò rẹ́.',
    'companion.cardPrayerLink': 'Ṣí àwọn àkókó àdúrà',
    'companion.cardHijriBody': 'Wo ọjọ́ ìlú Umm al-Qura tí ó ní àmì; àwọn ìkede àdúgbò lè yàtọ̀.',
    'companion.cardHijriLink': 'Ṣí ìfihàn ọjọ́',
    'companion.cardCounterBody': 'Tọ́jọ́ kíkà lórí ojú ìwé yìí láìfipamọ́ sí àkọ̀ọ̀ntọ̀ rẹ́.',
    'companion.cardCounterLink': 'Ṣí olùkàpọ̀',
    'companion.prayerHeading': 'Àwọn àkókó òde òní tí a ṣe ìṣiro',
    'companion.prayerLede':
      'Ìṣiro lè yàtọ̀ sí ti mọ́sálásì rẹ́ tàbí àwùjọ́ àdúgbò. Jẹ́rìí àwọn àkókó àdúrà àti àwọn àṣàyàn ìṣiro pẹ̀lú àwùjọ́ rẹ́, pàápàá jùlọ́ ní àwọn latitude gíga. A fi ìtọ́lẹ̀wà hàn fún ìtọ́kasẹ̀; kì í ṣe àdúrà.',
    'companion.prayerPrivacy':
      'A ń lo ibi lórí ẹ̀rọ̀ yìí a kò sì tọ́jọ́ rẹ́ kò sì fi ránṣẹ́ sí AyahSpring. Aṣàwákiri rẹ́ tàbí ètò ìṣiṣẹ́ rẹ́ lè lo olùpèsè ibi. Ìkọ̀ ẹ̀ẹ̀méjì yóò pa àwọn ìtẹ̀wọlé rẹ́; bọ́tì ìpadà aṣàwákiri lè mú wọn padà.',
