    'companion.prayerPrivacy':
      'Ahantu hakoreshwa kuri iki gikoresho ntabikwa kandi ntiyoherezwa AyahSpring. Umukoresha wawe cyangwa sisitemu yawe irashobora gukoresha umutanga ahantu. Gukoresha nabi kongera irabura ibyanditswe; buto yo gusubira y\'umukoresha irashobora kubisubiza.',
