    'companion.prayerMoonsightingNote':
      'Ubu buryo bukoresha ibyo bihinduka by\'ibihe n\'igipimo cy\'igice cya karindwi cy\'ijoro ku burebure bwa 55° cyangwa hejuru; ntabwo amategeko y\'ijoro atandukanye akeneye.',
