    'companion.prayerPrivacy':
      'Ampiasaina amin\'ity fitaovana ity ny toerana ary tsy voatahirizana na alefa any amin\'ny AyahSpring. Mety hampiasa mpamatsy toerana ny mpitety na ny rafitra fiasanao. Mamafa ny singa ny famerenana; mety hamaverina azy ny bokotra miverina amin\'ny mpitety.',
