    'companion.prayerExample':
      'Ny fitaovanao dia amin\'ny {zone}. Raha any amin\'ny {place} ny toerana misy anao, azonao raisina ny {method}; hamafiso amin\'ny moskeanao na ny manampahefana eo an-toerana aloha. Tsy mamantatra ny toerana misy anao ny faritra ora, ary mety hampiasana fomba hafa any.',
    'companion.prayerUseMethod': 'Ampiasao ity fomba ity',
