    'companion.prayerAsrNote':
      'Ny mahazatra dia mampiasa ny anton-javatra aloky iray; ny Hanafi dia mampiasa roa, ankoatra ny aloky ny mitataovovonana. Anontanio ny fiarahamoninao raha tsy matoky ianao.',
    'companion.prayerMoonsightingNote':
      'Mampiasa ny fanitsiana ara-potoana manokana sy ny tombana ampahafito amin\'ny alina amin\'ny latitude avaratra 55° na mihoatra ity fomba ity; tsy ilaina ny fitsipika alina misaraka.',
    'companion.prayerNightLabel': 'Fitsipika alina ho an\'ny latitude avo',
    'companion.prayerNightChoose': 'Fidio ny fitsipika alina',
