    'companion.prayerNightAngle': 'Zoro amin\'ny manga',
    'companion.prayerNightNote':
      'Mizara ny alina ireo fitsipika ireo hamerana ny Fajr sy ny Isha: ny antsasany, ny ampahafito, na ny ampahany mifototra amin\'ny zoro amin\'ny manga. Mety hampiasaina na dia any ivelan\'ny faritra polar aza. Anontanio ny fiarahamoninao izay fitsipika arahiny.',
    'companion.prayerNoPolar':
      'Tsy misy solon\'ny polar ampiasaina. Raha tsy azo kajiana ny andiana fotoana feno, manatona ny moskeanao eo an-toerana na ny manampahefana.',
    'companion.prayerZone': 'Ny faritra orana amin\'ny fitaovanao dia {zone}. Tsy maintsy mifanaraka amin\'ny fandrindrana izany, anisan\'izany ny ora fahavaratra.',
