    'companion.prayerMsgZoneChanged':
      'Niova ny faritra orana amin\'ny fitaovana. Jereo ny toerana misy anao, ny fomba fanao ary ny faritra oranao alohan\'ny kajy.',
    'companion.prayerMsgDateChanged': 'Niova ny daty. Jereo ny fandaminanao ary kajio indray.',
    'companion.prayerMsgNoGeo': 'Tsy misy ny toerana amin\'ity mpitety ity. Azonao ampidirina amin\'ny tanana ny fandrindrana.',
