    'companion.prayerMsgLocationDenied':
      'Tsy nisy ny toerana na nolavina ny fahazoan-dalana. Azonao ampidirina amin\'ny tanana ny fandrindrana.',
    'companion.prayerMsgIncomplete':
      'Ampidiro ny fandrindrana, fidio ny fandaminana ny kajy, ary hamafiso ny faritra orana amin\'ny fitaovanao.',
