    'companion.counterPrivacy':
      'আপনার গণনা সংরক্ষণ করা হয় না বা AyahSpring-এ পাঠানো হয় না। পুনরায় লোড করলে তা মুছে যায়। আপনি ফিরে এলে আপনার ব্রাউজার পৃষ্ঠাটি সাময়িকভাবে পুনরুদ্ধার করতে পারে। এটি ডিভাইস বা অ্যাকাউন্ট জুড়ে সিঙ্ক হয় না।',
