    'companion.hijriLede':
      'यह गणना की गई नागरिक तारीख है, चाँद देखने की घोषणा नहीं। स्थानीय धार्मिक तारीखें भिन्न हो सकती हैं; रमज़ान, ईद और अन्य अवसरों के लिए अपने समुदाय की घोषणाएँ जाँचें।',
    'companion.hijriClock':
      'तारीख आपके डिवाइस की घड़ी और समय क्षेत्र का उपयोग करती है और आधी रात को बदलती है, सूर्यास्त पर नहीं। ब्राउज़र कैलेंडर डेटा भिन्न हो सकता है। तारीख अपडेट करने के लिए रीफ़्रेश करें।',
