    'companion.counterOff': 'தனிப்பட்ட எண்ணி இயக்கப்படவில்லை.',
    'companion.counterLede': 'இந்தப் பக்கம் திறந்திருக்கும்போது எண்ணிக்கையை வைத்திருக்கும் எளிய கருவி.',
    'companion.counterPrivacy':
      'உங்கள் எண்ணிக்கை சேமிக்கப்படுவதில்லை, AyahSpring-க்கு அனுப்பப்படுவதுமில்லை. மீண்டும் ஏற்றினால் அது நீங்கும். நீங்கள் திரும்பும்போது உங்கள் உலாவி பக்கத்தைத் தற்காலிகமாக மீட்டெடுக்கலாம். இது சாதனங்கள் அல்லது கணக்குகளுக்கு இடையே ஒத்திசைக்கப்படுவதில்லை.',
    'companion.cardPrayerBody': 'உங்கள் சாதனத்தில் நேரங்களை மதிப்பிட்டு உங்கள் உள்ளூர் சமூகத்துடன் சரிபார்க்கவும்.',
