    'companion.cardHijriLink': 'தேதிக் காட்சியைத் திற',
    'companion.cardCounterBody': 'உங்கள் கணக்கில் சேமிக்காமல் இந்தப் பக்கத்தில் எண்ணிக்கையை வைத்திருங்கள்.',
