      'நேரங்கள் தானாக மீண்டும் கணக்கிடப்படுவதில்லை. தேதியைச் சரிபார்த்து, இருப்பிடம் அல்லது நேர மண்டல மாற்றத்திற்குப் பிறகு மீண்டும் கணக்கிடவும். தேதி அல்லது மண்டல மாற்றம் கண்டறியப்பட்டால் பழைய காட்சி நீங்கும்.',
