      'මෙම නීති ෆජ්ර් සහ ඉෂා සීමා කිරීමට රැය බෙදයි: භාගය, සත්වැන්න, හෝ අඳුරු කෝණය මත පදනම් වූ කොටස. ඒවා ධ්‍රැවීය ප්‍රදේශවලින් පිටත වුවද අදාළ විය හැකිය. ඔබේ ප්‍රජාව අනුගමනය කරන නීතිය කුමක්දැයි අසන්න.',
    'companion.prayerNoPolar':
      'ධ්‍රැවීය විකල්පයක් අදාළ කරනු නොලැබේ. සම්පූර්ණ වේලා කට්ටලයක් ගණනය කළ නොහැකි නම්, ඔබේ දේශීය මුස්ලිම් පල්ලිය හෝ අධිකාරිය හමුවන්න.',
    'companion.prayerZone': 'ඔබේ උපාංගුවේ කාල කලාපය {zone} වේ. එය ඛණ්ඩාංකවලට ගැලපිය යුතුය, දිවා ආලෝක ඉතිරිකිරීම ඇතුළුව.',
