    'companion.prayerMsgLocationDenied':
      'ස්ථානය නොමැති විය හෝ අවසරය ප්‍රතික්ෂේප විය. ඔබට ඛණ්ඩාංක අතින් ඇතුළත් කළ හැකිය.',
    'companion.prayerMsgIncomplete':
      'ඛණ්ඩාංක ඇතුළත් කරන්න, ගණනය කිරීමේ සැකසුම් තෝරන්න, සහ ඔබේ උපාංගුවේ කාල කලාපය තහවුරු කරන්න.',
    'companion.prayerMsgRange': '−90 සිට 90 අතර අක්ෂාංශයක් සහ −180 සිට 180 අතර දේශාංශයක් ඇතුළත් කරන්න.',
    'companion.prayerMsgZoneUnknown': 'ඔබේ උපාංගුවේ කාල කලාපය හඳුනාගත නොහැකි විය.',
    'companion.prayerMsgZoneChangedAgain': 'ඔබේ උපාංගුවේ කාල කලාපය වෙනස් විය. එය පරීක්ෂා කර නැවත තහවුරු කරන්න.',
    'companion.prayerMsgCannotCalculate':
      'මෙම ස්ථානය සහ දිනය සඳහා සම්පූර්ණ සහ ස්ථාවර වේලා කට්ටලයක් ගණනය කළ නොහැකි විය. ඉහළ අක්ෂාංශවල සාමාන්‍ය සූර්ය සිදුවීම් නොමැති විය හැකිය හෝ අනපේක්ෂිත අනුපිළිවෙලකින් තිබිය හැකිය. ස්ථානය සහ කාල කලාපය පරීක්ෂා කර ඔබේ දේශීය මුස්ලිම් පල්ලියේ හෝ අධිකාරියේ කාලසටහන අනුගමනය කරන්න. ධ්‍රැවීය ආසන්න කිරීමක් අදාළ කරනු නොලැබුණි.',
    'companion.hijriHeading': 'උම් අල්-කුරා සිවිල් දින දර්ශනය',
    'companion.hijriLede':
      'මෙය ගණනය කළ සිවිල් දිනයකි, චන්ද්‍ර දර්ශන නිවේදනයක් නොවේ. දේශීය ආගමික දිනයන් වෙනස් විය හැකිය; රමදාන්, ඊද් සහ අනෙකුත් අවස්ථා සඳහා ඔබේ ප්‍රජාවගේ නිවේදන පරීක්ෂා කරන්න.',
    'companion.hijriClock':
      'දිනය ඔබේ උපාංගුවේ ඔරලෝසුව සහ කාල කලාපය භාවිතා කරන අතර හිරු අවරට ගිය විට නොව මධ්‍යම රාත්‍රියේ වෙනස් වේ. බ්‍රවුසර දින දර්ශන දත්ත වෙනස් විය හැකිය. දිනය යාවත්කාල කිරීමට නැවත පූරණය කරන්න.',
