    'companion.counterOff': 'ޚާއްޞު ގިނާރު ހުދިފަސްކޮށްގެން ނެތް.',
    'companion.counterLede': 'މި ސަފްޙާ ހުޅިގެން އިރުވާލާ ގިނާރު ހިފަދުކުރުމަށް އެކި ވަސީލަތެއް.',
    'companion.counterPrivacy':
      'ތިބަވަން ގިނާރު ހިފަދުކޮށްގެން ނެތް، އާޔާސްޕްރިންގއަށް ވަޑުދެވެން ނެތް. ރީލޯޑް ކުރުން އެއީ މަސައްދެއް. ތިބަވަން ވަޑުދެވި އިރުވާލާ ސަފްޙާ ވަގުތީ ގޮތުން ރަސްކުރެވޭނެޭ. އެއީ ޑިވައިސް ވަޅި އެކައުންޓުތަކާ ސިންކްކުރެވެން ނެތް.',
    'companion.cardPrayerBody': 'ތިބަވަން ޑިވައިސްގައި ވަގުތު ތަޚްމީން ކުރައްވާށި، ތިބަވަން ލޯކަލް ޖަމާޢަތާ ތަސްދީޤު ކުރައްވާށި.',
    'companion.cardPrayerLink': 'ނަމާދު ވަގުތު ހުޅުލާށި',
    'companion.cardHijriBody': 'ލޭބަލު ކުރެވުމުވެގެން އުމުމުލް ޤުށްރާ ސިވިލް ތާރީޚް ބަލާށި؛ ލޯކަލް އިޢުލާންތައް ވެސްތަރިވެދޭނެޭ.',
