    'companion.cardCounterBody': 'ތިބަވަން އެކައުންޓުގައި ހިފަދުކޮށްގެން ނެތި މި ސަފްޙާގައި ގިނާރު ހިފަދުކުރައްވާށި.',
    'companion.cardCounterLink': 'ގިނާރު ހުޅުލާށި',
    'companion.prayerHeading': 'މިއަދަގެ ތަޚްމީން ކުރެވުމުވެގެން ވަގުތު',
    'companion.prayerLede':
      'ޙިސާބުތައް ތިބަވަން މަސްޖިދުން ވަޅި ލޯކަލް އަތޯރިޓީއާ ވެސްތަރިވެދޭނެޭ. ނަމާދު ވަގުތާއި ޙިސާބުކުރުމުގެ ޚިޔާރާތައް ތިބަވަން ޖަމާޢަތާ ތަސްދީޤު ކުރައްވާށި، ޚާއްޞަތަކަން މަތީންގައި. އަލިފަން ވެޑުމުވެގެން ދައްކަވާލީ؛ އެއީ ނަމާދެއް ނޫން.',
    'companion.prayerPrivacy':
      'މަޤާމް މި ޑިވައިސްގައި ބޭނުންވެޭ، ހިފަދުކޮށްގެން ނެތް، އާޔާސްޕްރިންގއަށް ވަޑުދެވެން ނެތް. ތިބަވަން ބްރައުޒަރު ވަޅި އޮޕަރޭޓިންގ ސިސްޓަމް މަޤާމު ޕްރޮވައިޑަރެއް ބޭނުންވެދޭނެޭ. ރީލޯޑް ކުރުން އެންޓްރީތައް މަސައްދެއް؛ ބްރައުޒަރުގެ ބެކް ބަޓަން އެންޓްރީތައް ރަސްކުރެވޭނެޭ.',
